'use strict';
function weaponSkillText(id){const d=WEAPON_SKILLS[id];if(!d)return '';const rank=player.weaponSkills[id]||1;return 'ACTIVE · ขั้น '+d.tier+' · Lv.'+rank+'/30\nอาวุธหลัก: '+WEAPON_NAMES[d.weapon]+'\nCD '+(d.cd===null?'เปิด–ปิด ไม่ใช้ CD':d.cd+' วิ')+' · MP '+skillManaCost(d,rank)+' ('+d.tier+' × Lv + '+d.tier*5+')\n'+d.damageLabel+'\n'+d.hitLabel+'\n'+d.rangeLabel+'\n'+d.effects+chargeDamageDetail(d)+(d.weapon==='staff'&&[2,3].includes(d.tier)?'\nเริ่ม CD หลังปล่อยสกิล':'')+(d.cd===null?'\nMP ตามสูตรทุก 1 วินาที':'')}
function skillPreview(cell,id){if(id)attachLootDetail(cell,{name:WEAPON_SKILLS[id].name,description:weaponSkillText(id)})}
function openWeaponSkillDetail(id){const d=WEAPON_SKILLS[id];if(!d)return;const lv=player.weaponSkills[id]||1;modal(d.name+' · Lv.'+lv+'/30',weaponSkillText(id)+'\nสกิลซ้ำ '+(player.skillScrolls[id]||0)+' ชิ้น · โอกาสอัป '+upgradeWeaponChance(lv+1)+'%',[['อัปด้วยสกิลซ้ำ',()=>{learnOrUpgradeWeaponSkill(id);if(!$('characterOverlay').hidden)renderInventory();openWeaponSkillDetail(id)},true]]);$('modalButtons').firstElementChild.disabled=lv>=30||!(player.skillScrolls[id]>0)}
function renderSwordSkillWindow(body){ensureBaselineSkills(player);body.className='weapon-skill-window';body.replaceChildren();$('modalTitle').textContent='ชุดสกิลอาวุธ · Active';const grid=document.createElement('div');grid.className='active-loadout-grid';for(let tier=1;tier<=4;tier++){const row=document.createElement('section');row.className='active-loadout-row';const id=player.weaponLoadout[tier-1].active[0],locked=player.level<SKILL_MIN_LEVEL[tier]||player.classTier<tier;const heading=document.createElement('strong');heading.textContent='ขั้น '+tier+' · '+'QWER'[tier-1];const cell=document.createElement('div');cell.className='weapon-skill-cell';cell.tabIndex=0;cell.textContent=locked?'Lv.'+SKILL_MIN_LEVEL[tier]:id?WEAPON_SKILLS[id].name+'\nLv.'+player.weaponSkills[id]+(weaponSkillEnabled(id)?'':'\nอาวุธไม่ตรง'):'ว่าง';skillPreview(cell,id);const change=document.createElement('button');change.className='skill-detail-action';change.textContent='เปลี่ยนสกิล';change.disabled=locked;change.onclick=()=>pickWeaponSkill(tier,'active',0);row.append(heading,cell,change);grid.append(row)}body.append(grid);const note=document.createElement('p');note.textContent='Active 48 สกิล · สกิลเริ่ม Lv.1 · ใช้สกิลซ้ำจากกล่องเพื่ออัปถึง Lv.30 · สวมอาวุธหลักให้ตรงกับสกิล';body.append(note)}
function pickWeaponSkill(tier,kind,index){ensureBaselineSkills(player);hideUpgradeTooltip();const body=document.createElement('div');body.className='weapon-picker-panel';const tabs=document.createElement('div');tabs.className='weapon-picker-tabs';const rows=document.createElement('div');rows.className='weapon-picker-rows';let weapon=weaponInHand('main')||validClass().weapons[0];function render(){rows.replaceChildren();for(const b of tabs.children)b.classList.toggle('selected',b.dataset.weapon===weapon);const heading=document.createElement('h3');heading.textContent=WEAPON_NAMES[weapon]+' · ขั้น '+tier;rows.append(heading);for(const d of Object.values(WEAPON_SKILLS).filter(d=>d.tier===tier&&d.weapon===weapon)){const row=document.createElement('div');row.className='weapon-picker-row';row.tabIndex=0;skillPreview(row,d.id);const icon=document.createElement('span');icon.innerHTML=weaponIcon(weapon);const label=document.createElement('span');label.textContent=d.name;const rank=document.createElement('strong');rank.textContent=player.weaponSkills[d.id]+'/30';const choose=document.createElement('button');choose.textContent='เลือก';choose.disabled=!weaponSkillEnabled(d.id);choose.onclick=()=>{if(equipPooledSkill(d.id,index)){hideUpgradeTooltip();closeModal();openControlWindow('skill')}};row.append(icon,label,rank,choose);rows.append(row)}}for(const w of Object.keys(WEAPON_NAMES)){const b=document.createElement('button');b.dataset.weapon=w;b.innerHTML=weaponIcon(w);b.title=WEAPON_NAMES[w];b.setAttribute('aria-label',WEAPON_NAMES[w]);b.onclick=()=>{weapon=w;hideUpgradeTooltip();render()};tabs.append(b)}body.append(tabs,rows);modal('เปลี่ยนสกิล · ขั้น '+tier,body,[['ถอดสกิล',()=>{stopActiveChannels();player.weaponLoadout[tier-1].active=[null];save();closeModal();openControlWindow('skill')}],['กลับ',()=>{closeModal();openControlWindow('skill')}]]);render()}
function updateWeaponHUD(){for(const [i,key]of ['q','w','e','r'].entries()){const id=player.weaponLoadout[i].active[0],b=$('hotbar'+key.toUpperCase());player.skillSlots[key]=id;b.disabled=!weaponSkillEnabled(id)||((player.cd[id]||0)>0&&player.activeChannel?.id!==id);b.querySelector('span').textContent=id?WEAPON_SKILLS[id].name:'ว่าง';if(b.querySelector('em'))b.querySelector('em').textContent=player.cd[id]>0?Number(player.cd[id].toFixed(1)):player.activeToggles?.[id]?'ON':'';b.title=id?weaponSkillText(id):'เลือกสกิลขั้น '+(i+1)}updateBuffHUD()}
function updateBuffHUD(){const hud=$('buffHUD');hud.replaceChildren();const labels=[];for(const [key,value]of Object.entries(player.activeBuffs||{}))if(value>0)labels.push([key==='fist'?'ฟิลด์พิเศษ':'ปลดชาร์จ',Math.ceil(value)+' วิ']);for(const id of Object.keys(player.activeToggles||{}))if(player.activeToggles[id])labels.push([WEAPON_SKILLS[id].name,'ON']);for(const [name,value]of labels){const b=document.createElement('div');b.className='buff-placeholder';b.title=name;b.textContent=value;hud.append(b)}}



function chargeDamageDetail(d){if(d.weapon==='staff'&&d.tier===2)return '\nชาร์จเพิ่มดาเมจ 60→120%';if(d.weapon==='staff'&&d.tier===3)return '\nชาร์จเพิ่มดาเมจ 25→150%';if(d.weapon==='crossbow'&&d.tier===3)return '\nชาร์จเพิ่มดาเมจ 75→150%';if(d.weapon==='spear'&&d.tier===4)return '\nชาร์จเพิ่มดาเมจรวม 100→200%';if(d.weapon==='hammer'&&d.tier===3)return '\nระดับชาร์จ 1/2/3: 50/100/150%';return ''}
